CREATE TABLE "sedes" (
  "id_sede" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(150) NOT NULL,
  "direccion" varchar(250),
  "estado" boolean DEFAULT true,
  "created_at" timestamp
);

CREATE TABLE "facultades" (
  "id_facultad" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(150) NOT NULL,
  "estado" boolean DEFAULT true,
  "created_at" timestamp
);

CREATE TABLE "carreras" (
  "id_carrera" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_facultad" int NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "estado" boolean DEFAULT true,
  "created_at" timestamp
);

CREATE TABLE "areas" (
  "id_area" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(150) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true,
  "created_at" timestamp
);

CREATE TABLE "roles" (
  "id_rol" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(80) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "usuarios" (
  "id_usuario" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(30) UNIQUE,
  "nombres" varchar(120) NOT NULL,
  "apellidos" varchar(120) NOT NULL,
  "correo" varchar(180) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "telefono" varchar(30),
  "id_rol" int NOT NULL,
  "id_sede" int,
  "id_facultad" int,
  "id_carrera" int,
  "id_area" int,
  "estado" boolean DEFAULT true,
  "ultimo_acceso" timestamp,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "tipos_ticket" (
  "id_tipo_ticket" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(10) UNIQUE NOT NULL,
  "nombre" varchar(80) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "prioridades" (
  "id_prioridad" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(50) NOT NULL,
  "nivel" int NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "estados" (
  "id_estado" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(80) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "categorias" (
  "id_categoria" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(120) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "subcategorias" (
  "id_subcategoria" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_categoria" int NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "servicios" (
  "id_servicio" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_area" int NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "descripcion" varchar(250),
  "estado" boolean DEFAULT true
);

CREATE TABLE "tickets" (
  "id_ticket" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(30) UNIQUE NOT NULL,
  "id_tipo_ticket" int NOT NULL,
  "id_usuario_solicitante" int NOT NULL,
  "id_area" int NOT NULL,
  "id_servicio" int,
  "id_categoria" int,
  "id_subcategoria" int,
  "id_prioridad" int NOT NULL,
  "id_estado" int NOT NULL,
  "titulo" varchar(200) NOT NULL,
  "descripcion" text NOT NULL,
  "fecha_creacion" timestamp NOT NULL,
  "fecha_asignacion" timestamp,
  "fecha_inicio_atencion" timestamp,
  "fecha_resolucion" timestamp,
  "fecha_cierre" timestamp,
  "solucion" text,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "asignaciones" (
  "id_asignacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int NOT NULL,
  "id_especialista" int NOT NULL,
  "asignado_por" int,
  "fecha_asignacion" timestamp NOT NULL,
  "fecha_fin" timestamp,
  "motivo_reasignacion" varchar(250),
  "activo" boolean DEFAULT true
);

CREATE TABLE "comentarios" (
  "id_comentario" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int NOT NULL,
  "id_usuario" int NOT NULL,
  "comentario" text NOT NULL,
  "comentario_interno" boolean DEFAULT false,
  "created_at" timestamp NOT NULL
);

CREATE TABLE "adjuntos" (
  "id_adjunto" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int NOT NULL,
  "id_usuario" int NOT NULL,
  "nombre_archivo" varchar(255) NOT NULL,
  "ruta_archivo" varchar(500) NOT NULL,
  "tipo_archivo" varchar(100),
  "tamanio" bigint,
  "created_at" timestamp
);

CREATE TABLE "historial_ticket" (
  "id_historial" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int NOT NULL,
  "id_usuario" int NOT NULL,
  "accion" varchar(150) NOT NULL,
  "campo_modificado" varchar(100),
  "valor_anterior" text,
  "valor_nuevo" text,
  "fecha" timestamp NOT NULL
);

CREATE TABLE "politicas_sla" (
  "id_sla" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_tipo_ticket" int,
  "id_prioridad" int NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "tiempo_primera_respuesta_min" int NOT NULL,
  "tiempo_resolucion_min" int NOT NULL,
  "estado" boolean DEFAULT true
);

CREATE TABLE "ticket_sla" (
  "id_ticket_sla" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int NOT NULL,
  "id_sla" int NOT NULL,
  "fecha_limite_respuesta" timestamp,
  "fecha_limite_resolucion" timestamp,
  "fecha_respuesta_real" timestamp,
  "fecha_resolucion_real" timestamp,
  "cumplio_respuesta" boolean,
  "cumplio_resolucion" boolean
);

CREATE TABLE "crq_detalle" (
  "id_crq" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int UNIQUE NOT NULL,
  "tipo_trabajo" varchar(120) NOT NULL,
  "motivo" text,
  "descripcion_tecnica" text,
  "fecha_programada" date,
  "hora_inicio" time,
  "hora_fin_estimada" time,
  "impacto" varchar(50),
  "riesgo" varchar(50),
  "usuarios_afectados" int,
  "plan_trabajo" text,
  "plan_pruebas" text,
  "plan_reversa" text,
  "resultado_final" text,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "crq_aprobaciones" (
  "id_aprobacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_crq" int NOT NULL,
  "id_aprobador" int NOT NULL,
  "estado_aprobacion" varchar(50) NOT NULL,
  "comentario" text,
  "fecha_aprobacion" timestamp
);

CREATE TABLE "notificaciones" (
  "id_notificacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" int NOT NULL,
  "id_ticket" int,
  "titulo" varchar(180) NOT NULL,
  "mensaje" text NOT NULL,
  "leida" boolean DEFAULT false,
  "fecha" timestamp NOT NULL
);

CREATE TABLE "encuestas" (
  "id_encuesta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ticket" int UNIQUE NOT NULL,
  "id_usuario" int NOT NULL,
  "calificacion" int NOT NULL,
  "comentario" text,
  "fecha" timestamp
);

COMMENT ON TABLE "tipos_ticket" IS 'REQ = Requerimiento, INC = Incidente, CRQ = Cambio/Mantenimiento/Trabajo';

